function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#051428', Shell='#335d92', ShellLt='#5384bb', ShellDk='#234775';
  const Metal='#b3b0a9', MetalLt='#c2bfb7', MetalDk='#6b6e73';
  const Label='#f0e8d6', Ink='#0f1419', Shine='#ffffff';
  // arms
  px(2,16,4,5,Shell); px(2,16,1,5,O); px(26,16,4,5,Shell); px(29,16,1,5,O);
  // shell
  px(5,3,22,21,Shell); px(6,2,20,1,Shell);
  px(6,2,20,1,O); px(5,3,1,20,O); px(26,3,1,20,O); px(6,23,20,1,O);
  px(6,3,1,19,ShellLt); px(25,4,1,18,ShellDk);
  // notch
  px(24,20,3,4,'#00000000'); ctx.clearRect(24,20,3,4);
  // shutter
  px(9,3,14,7,Metal); px(9,3,14,1,MetalLt); px(9,9,14,1,MetalDk);
  px(12,4,6,5,MetalDk); px(13,5,4,3,O);
  // face
  px(8,11,16,11,Label); px(11,14,3,3,Ink); px(18,14,3,3,Ink);
  px(11,14,1,1,Shine); px(18,14,1,1,Shine); px(12,19,5,1,Ink);
  // legs
  px(10,24,4,4,ShellDk); px(18,24,4,4,ShellDk);
  px(9,27,6,3,Shell); px(17,27,6,3,Shell);

}
